"""第二批答案页（links 已校正为现存 SKU）"""
NEW = [
 {'slug': '8mm-vs-1-4-inch-shank', 'q': 'Is an 8 mm shank the same as 1/4 inch?', 'a': 'No. 8 mm is 0.315 in and 1/4 in is 6.35 mm; they differ by 1.65 mm and need different collets.', 'body': '<table><tr><th>Shank</th><th>Metric</th><th>Imperial</th><th>Fits</th></tr><tr><td>1/4 in</td><td>6.35 mm</td><td>1/4 in</td><td>US routers, most trim routers</td></tr><tr><td>6 mm</td><td>6 mm</td><td>—</td><td>European and Asian collets</td></tr><tr><td>8 mm</td><td>8 mm</td><td>0.315 in</td><td>8 mm collet only</td></tr></table><p><b>The mistake:</b> clamping an 8 mm bit in a 1/4 in collet. It slips, scores the collet and can throw the bit. Measure the shank with calipers before ordering.</p>', 'answer_short': 'No — 8 mm (0.315 in) and 1/4 in (6.35 mm) differ by 1.65 mm and need different collets.', 'links': ['RB-12Z8', 'RB-15Z8']},
 {'slug': 'metric-vs-imperial-drill-bits', 'q': 'Metric or imperial drill bits: does the difference matter?', 'a': 'Yes. A 6 mm bit is not a 1/4 in bit; the gap is 0.35 mm, which is enough to ruin a press fit.', 'body': '<table><tr><th>Metric</th><th>Nearest imperial</th><th>Gap</th></tr><tr><td>6 mm</td><td>1/4 in (6.35 mm)</td><td>0.35 mm</td></tr><tr><td>8 mm</td><td>5/16 in (7.94 mm)</td><td>0.06 mm</td></tr><tr><td>10 mm</td><td>3/8 in (9.53 mm)</td><td>0.47 mm</td></tr><tr><td>13 mm</td><td>1/2 in (12.70 mm)</td><td>0.30 mm</td></tr></table><p><b>Where it bites:</b> tapping and press fits. A 0.35 mm oversize hole gives a loose thread; undersize snaps the tap. Match the standard the drawing uses.</p>', 'answer_short': "Yes. 6 mm and 1/4 in differ by 0.35 mm, enough to spoil a tapped hole or a press fit. Match the drawing's standard.", 'links': ['DB-13M', 'DB-21M']},
 {'slug': 'drill-point-angle-118-vs-135', 'q': '118 or 135 degree drill point: which do I need?', 'a': '118 degrees for wood, plastics and soft steel; 135 degrees split point for stainless and hard alloys because it walks less.', 'body': '<table><tr><th>Point</th><th>Behaviour</th><th>Use for</th></tr><tr><td>118°</td><td>Aggressive, can wander on curved surfaces</td><td>Wood, plastic, mild steel</td></tr><tr><td>135° split</td><td>Self-centering, thinner web</td><td>Stainless, hardened steel, sheet metal</td></tr></table><p><b>The mistake:</b> buying 118° bits for stainless because they are cheaper. They skate across the surface, work-harden the steel and burn the tip.</p>', 'answer_short': '118° for wood and mild steel, 135° split point for stainless and hard alloys. The split point stops the bit walking and work-hardening the surface.', 'links': ['DB-51C', 'DB-13M']},
 {'slug': 'hole-saw-tpi-and-arbor', 'q': 'What TPI hole saw do I need, and why do I need a separate arbor?', 'a': '4/6 TPI variable pitch for wood and metal; arbors are sold separately because they set the size range and fit your chuck.', 'body': '<table><tr><th>TPI</th><th>Use for</th></tr><tr><td>3–4</td><td>Wood, plastic, thick stock</td></tr><tr><td>4/6 variable</td><td>Sheet metal, mixed material (the default)</td></tr><tr><td>10+</td><td>Thin sheet, stainless</td></tr></table><p><b>Arbor:</b> carries the pilot drill and sets the thread the saw screws onto (1/2-20 or 5/8-18). A saw without the matching arbor cannot be used.</p><p><b>The mistake:</b> buying a saw with no arbor, or an arbor that does not match the thread.</p>', 'answer_short': '4/6 TPI variable pitch covers wood and sheet metal. The saw threads onto a specific arbor (1/2-20 or 5/8-18), so the pair must match.', 'links': ['HS-8']},
 {'slug': 'tap-drill-size-chart', 'q': 'What drill size do I use before tapping M3 to M12?', 'a': 'Subtract the pitch from the diameter for a 75% thread. M3x0.5 takes 2.5 mm, M6x1 takes 5.0 mm, M10x1.5 takes 8.5 mm, M12x1.75 takes 10.2 mm.', 'body': '<table><tr><th>Tap</th><th>Drill</th><th>Tap</th><th>Drill</th></tr><tr><td>M3 x 0.5</td><td>2.5 mm</td><td>M8 x 1.25</td><td>6.8 mm</td></tr><tr><td>M4 x 0.7</td><td>3.3 mm</td><td>M8 x 1.0</td><td>7.0 mm</td></tr><tr><td>M5 x 0.8</td><td>4.2 mm</td><td>M10 x 1.5</td><td>8.5 mm</td></tr><tr><td>M6 x 1.0</td><td>5.0 mm</td><td>M12 x 1.75</td><td>10.2 mm</td></tr></table><p><b>Formula:</b> drill = diameter − pitch (75% thread). Oversize means a stripped thread; undersize snaps the tap.</p>', 'answer_short': 'Drill size = nominal diameter minus pitch: M3x0.5 → 2.5 mm, M6x1 → 5.0 mm, M10x1.5 → 8.5 mm, M12x1.75 → 10.2 mm.', 'links': ['TD-40', 'TD-40T']},
 {'slug': 'npt-vs-bsp-threads', 'q': 'NPT or BSP: how do I tell which thread a fitting is?', 'a': 'NPT is the US standard (60 degree, tapered), BSP is British (55 degree). They do not seal against each other.', 'body': '<table><tr><th></th><th>NPT</th><th>BSP</th></tr><tr><td>Thread angle</td><td>60°</td><td>55°</td></tr><tr><td>Where used</td><td>US, Canada</td><td>UK, EU, Asia</td></tr><tr><td>1/2 in outside diameter</td><td>≈20.9 mm</td><td>≈20.9 mm (looks similar)</td></tr></table><p><b>The trap:</b> 1/2 in NPT and 1/2 in BSP look almost identical and thread a few turns before leaking. Count threads per inch or use a thread gauge.</p>', 'answer_short': 'NPT is 60° tapered (US), BSP is 55° (UK, EU, Asia). Half-inch sizes look nearly identical and will partially thread before leaking.', 'links': ['TD-40']},
 {'slug': 'what-is-hrc-in-end-mills', 'q': 'What does HRC mean on an end mill, and do I need the higher number?', 'a': 'HRC is the hardness of the workpiece the bit is designed for, not the hardness of the bit. Higher HRC handles harder steel but is more brittle.', 'body': '<table><tr><th>Grade</th><th>Workpiece</th><th>Trade-off</th></tr><tr><td>HRC45–55</td><td>Mild steel, stainless, aluminium</td><td>Tougher, forgiving</td></tr><tr><td>HRC60–65</td><td>Hardened steel to 62 HRC</td><td>Brittle, chips on chatter</td></tr><tr><td>HRC70</td><td>Hard milling only</td><td>Very brittle, rigid machines only</td></tr></table><p><b>The mistake:</b> buying HRC65 for general work and breaking it on the first interrupted cut. On a light machine, HRC55 usually finishes more parts before failing.</p>', 'answer_short': 'HRC describes the workpiece hardness the end mill is built for. HRC55 covers mild steel and stainless; HRC65 is for hardened steel and chips easily on light machines.', 'links': ['DB-51C', 'TD-40']},
 {'slug': 'upcut-downcut-compression-router-bits', 'q': 'Up-cut, down-cut or compression router bit: which for plywood and veneer?', 'a': 'Down-cut for a clean top face, up-cut for chip clearance, compression for clean faces on both sides of plywood.', 'body': '<table><tr><th>Type</th><th>Clean face</th><th>Use for</th></tr><tr><td>Up-cut</td><td>Bottom (tears top)</td><td>Deep cuts, fast chip removal</td></tr><tr><td>Down-cut</td><td>Top</td><td>Veneer, laminate, template work</td></tr><tr><td>Compression</td><td>Both</td><td>Plywood and double-sided veneer</td></tr></table><p><b>The mistake:</b> using an up-cut bit on veneered plywood and blowing out the top face you can see.</p>', 'answer_short': 'Down-cut for a clean top surface, up-cut for chip clearance, compression for clean faces on both sides of plywood. Up-cut bits tear the visible top face.', 'links': ['RB-12W', 'RB-15W']},
 {'slug': 'diamond-blade-arbor-sizes', 'q': 'Diamond blades come in 7/8 in and 20 mm bores — which fits my grinder?', 'a': 'Most US angle grinders use a 7/8 in (22.23 mm) arbor; many imported machines use 20 mm.', 'body': '<table><tr><th>Bore</th><th>Fits</th></tr><tr><td>7/8 in (22.23 mm)</td><td>US angle grinders, most 4.5 in tools</td></tr><tr><td>20 mm</td><td>Many EU and Asian grinders</td></tr><tr><td>5/8-11 threaded</td><td>US grinders that take threaded accessories</td></tr></table><p><b>Fix:</b> use a 22.23 to 20 mm reducing ring. Never run a loose blade: vibration cracks the core.</p>', 'answer_short': 'US angle grinders are usually 7/8 in (22.23 mm); many imported machines are 20 mm. Use a reducing ring rather than running a loose blade.', 'links': ['HS-8']},
 {'slug': 'carbide-burr-shapes', 'q': 'Carbide burr shapes: what do the letters A, C, D, E, F, G, H, L, M, N mean?', 'a': 'They are standard head shapes: A cylinder, C ball, D ball-nose cylinder, E oval, F round-nose tree, G pointed tree, H flame, L taper, M cone, N inverted cone.', 'body': '<table><tr><th>Code</th><th>Shape</th><th>Typical job</th></tr><tr><td>A</td><td>Cylinder</td><td>Deburring flat edges</td></tr><tr><td>C</td><td>Ball</td><td>Hollowing, radius work</td></tr><tr><td>D</td><td>Ball-nose cylinder</td><td>Contoured pockets</td></tr><tr><td>F</td><td>Round-nose tree</td><td>Die finishing</td></tr><tr><td>G</td><td>Pointed tree</td><td>Internal corners</td></tr><tr><td>H</td><td>Flame</td><td>Weld blending</td></tr><tr><td>L, M, N</td><td>Taper, cone, inverted cone</td><td>Chamfers, port work, back cuts</td></tr></table><p><b>Cut type matters too:</b> single cut for chip clearance and fast removal, double cut for a smoother finish and better control.</p>', 'answer_short': 'The letters are head shapes: A cylinder, C ball, D ball-nose, E oval, F round-nose tree, G pointed tree, H flame, L taper, M cone, N inverted cone.', 'links': ['CB-10D', 'CB-10S']},
]